def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = {}
    history = []  # stack of revert callbacks / inverse actions
    rejected = []

    def digits(s):
        return s.isdigit()

    for i, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0] if t else ""

        if verb == "open":
            if len(t) != 3 or not digits(t[2]) or not t[2]:
                rejected.append(i); continue
            n = int(t[2])
            if t[1] in balances:
                rejected.append(i); continue
            balances[t[1]] = n
            frozen[t[1]] = False
            a = t[1]
            def revert_open(a=a):
                del balances[a]; del frozen[a]
            history.append(revert_open)

        elif verb == "deposit":
            if len(t) != 3 or not t[2].isdigit():
                rejected.append(i); continue
            n = int(t[2])
            a = t[1]
            if n <= 0 or a not in balances:
                rejected.append(i); continue
            balances[a] += n
            def revert_dep(a=a, n=n):
                balances[a] -= n
            history.append(revert_dep)

        elif verb == "withdraw":
            if len(t) != 3 or not t[2].isdigit():
                rejected.append(i); continue
            n = int(t[2])
            a = t[1]
            if n <= 0 or a not in balances or frozen[a] or balances[a] < n:
                rejected.append(i); continue
            balances[a] -= n
            def revert_wd(a=a, n=n):
                balances[a] += n
            history.append(revert_wd)

        elif verb == "transfer":
            if len(t) != 4 or not t[3].isdigit():
                rejected.append(i); continue
            n = int(t[3]); a, b = t[1], t[2]
            if (n <= 0 or a == b or a not in balances or b not in balances
                    or frozen[a] or balances[a] < n):
                rejected.append(i); continue
            balances[a] -= n; balances[b] += n
            def revert_tr(a=a, b=b, n=n):
                balances[a] += n; balances[b] -= n
            history.append(revert_tr)

        elif verb == "freeze":
            if len(t) != 2:
                rejected.append(i); continue
            a = t[1]
            if a not in balances or frozen[a]:
                rejected.append(i); continue
            frozen[a] = True
            def revert_fr(a=a):
                frozen[a] = False
            history.append(revert_fr)

        elif verb == "unfreeze":
            if len(t) != 2:
                rejected.append(i); continue
            a = t[1]
            if a not in balances or not frozen[a]:
                rejected.append(i); continue
            frozen[a] = False
            def revert_uf(a=a):
                frozen[a] = True
            history.append(revert_uf)

        elif verb == "undo":
            if len(t) != 1 or not history:
                rejected.append(i); continue
            history.pop()()

        else:
            rejected.append(i)

    return balances, rejected
